import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {OUT,read} from './review-brake-alias-groups-20261025.mjs';
import {augmentSources} from './brake-alias-review-policy-20261025.mjs';
const dir=path.join(OUT,'交叉审核资料');fs.mkdirSync(dir,{recursive:true});
const summary=read(path.join(OUT,'final-summary.json')),questions=read(path.join(OUT,'shared-questions.json')).filter(q=>q.true_conflict_or_multi);
const qids=new Set(questions.map(q=>q.question_id)),targets=read(path.join(OUT,'remaining-review.json')).filter(r=>qids.has(r.question_id));
const raw=read('outputs/brake-pad-expansion-20261024/confirmation-data.json').sourceRows,catalog=read('data/brake-pads/catalog.json'),sources=augmentSources(raw,catalog);
const relevantIds=new Set(targets.flatMap(r=>[...r.source_ids,...r.platform_source_ids]));
const selected=sources.filter(s=>relevantIds.has(s.source_id));
const originalIds=new Set(selected.map(s=>s.original_source_id).filter(Boolean));
const evidenceSources=[...selected,...sources.filter(s=>originalIds.has(s.source_id)&&!relevantIds.has(s.source_id))];
const dump=(n,data)=>fs.writeFileSync(path.join(dir,n),JSON.stringify(data,null,2));
dump('待确认共享问题_121题.json',questions);dump('待确认目标_599位置.json',targets);dump('关联源记录.json',evidenceSources);dump('覆盖率与分类汇总.json',summary);
dump('已核实分组规则.json',read(path.join(OUT,'rule-group-review.json')));
const plan=read(path.join(OUT,'plan.json'));dump('车型归属合并追溯.json',plan.corrections.map(({before,...r})=>r));
const xlsx='NexAuto_热门50刹车片_分组复核与待确认_2026-10-25.xlsx';fs.copyFileSync(path.join(OUT,xlsx),path.join(dir,xlsx));
fs.copyFileSync(path.join(OUT,'处理结果说明.txt'),path.join(dir,'处理结果说明.txt'));
fs.writeFileSync(path.join(dir,'资料包说明.txt'),`本包为2026-10-25分组复核后的数据交付，不会自行写入数据库。\n\n工作簿包含：处理汇总、121个待确认共享问题、全部历史待审明细、178条已恢复发布、38条车型归属合并追溯、热门50逐车型覆盖率。黄色列可回填。\n\n121题只包含多候选、现网DB冲突、制动配置差异、年份内DB变化、唯一候选与旧DB不同、历史否决等需确认项，共599个application×位置。分组只共享资料检索，不能假设组内所有车身/年份/发动机共用一个DB。\n\n底盘映射缺失、源年份不足等另留在工作簿待审明细。549个位置的旧候选已有现网唯一源支持，不纳入重复研究。\n\n研究方案可由接收方自行决定。结果需给出具体DB、适用配置/年份及证据；仅确认车型身份并不能直接录入适配。无法确定可留空，不按多数票或可售SKU数量判断。\n\n关联源记录供程序检索，保留结束年0及原始配置，不把未知结束年当作无限适用。完整原始供应商表未改动。\n`);
const files=fs.readdirSync(dir).filter(n=>n!=='manifest.json').map(name=>({name,bytes:fs.statSync(path.join(dir,name)).size,sha256:crypto.createHash('sha256').update(fs.readFileSync(path.join(dir,name))).digest('hex')}));
dump('manifest.json',{generated_at:new Date().toISOString(),questions:questions.length,application_positions:targets.length,normalized_source_rows:evidenceSources.length,production_changes_in_package:false,files});
console.log(JSON.stringify({dir,questions:questions.length,targets:targets.length,sources:evidenceSources.length,files:files.length+1},null,2));
